#!/usr/bin/env bash
# TAUSIK CLI wrapper — always uses .tausik/venv Python
# Generated by bootstrap. Do not edit manually.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_DIR="$(dirname "$SCRIPT_DIR")"

# Use the profile selected and recorded by bootstrap. A stale sibling profile
# must never win merely because its directory sorts first.
IDE_LIST="__IDE_LIST__"
PRIMARY_IDE="__PRIMARY_IDE__"
SCRIPTS="$PROJECT_DIR/__PROFILE_DIR__/scripts"
if [ ! -f "$SCRIPTS/project.py" ]; then
    echo "Error: configured TAUSIK profile '$PRIMARY_IDE' has no scripts/project.py; rerun bootstrap --ide $PRIMARY_IDE" >&2
    exit 1
fi

# Force UTF-8 stdio so Unicode output (Cyrillic, ✓/→) never hits a
# cp1251/cp1252 console encoder and raises UnicodeEncodeError on Windows.
export PYTHONUTF8=1

# Find Python: prefer .tausik/venv, fallback to system
if [ -f "$SCRIPT_DIR/venv/bin/python" ]; then
    PYTHON="$SCRIPT_DIR/venv/bin/python"
elif [ -f "$SCRIPT_DIR/venv/Scripts/python.exe" ]; then
    PYTHON="$SCRIPT_DIR/venv/Scripts/python.exe"
else
    PYTHON="python"
fi

exec "$PYTHON" "$SCRIPTS/project.py" "$@"
